/**
 * Save contents of the file at the specified path to a Mendix FileDocument.
 * 
 * Note that you cannot write content directly to a Mendix file document. You can use the writeFile action to write base64 encoded content to a file and then call this action to save the contents in the Mendix object.
 * @param {string} filepath - The path to the file or directory.
 * @param {undefined|"FullPath"|"DocumentsDirectory"} pathType
 * @param {MxObject} fileDocument
 * @param {string} fileName
 * @param {boolean} writeToLog
 * @returns {Promise.<boolean>}
 */
export async function saveToMendixFileDocument(filepath, pathType, fileDocument, fileName, writeToLog) {
	// BEGIN USER CODE

	if (!filepath) {
		return Promise.reject(new Error("No file path specified"));
	}
	if (!pathType) {
		return Promise.reject(new Error("No path type specified"));
	}
	if (!fileDocument) {
		return Promise.reject(new Error("No file document specified"));
	}
    if (!fileDocument.inheritsFrom("System.FileDocument")) {
        const entity = picfileDocumentture.getEntity();
        return Promise.reject(new Error("Entity " + entity + " does not inherit from System.FileDocument"));
    }
	if (!fileName) {
		return Promise.reject(new Error("No file name specified"));
	}
	const guid = fileDocument.getGuid();
	if (writeToLog) {
		await NativeFileDocumentsUtils.writeToLog({
			actionName: "saveToMendixFileDocument",
			logType: "Parameters",
			logMessage: JSON.stringify({
				filepath: filepath,
				pathType: pathType,
				guid: guid
			})
		});
	}

	const fullPath = NativeFileDocumentsUtils.getFullPath(filepath, pathType, RNBlobUtil, Platform.OS);

	if (writeToLog) {
		await NativeFileDocumentsUtils.writeToLog({
			actionName: "saveToMendixFileDocument",
			logType: "Info",
			logMessage: "Full path: " + fullPath
		});
	}

	// Code based on NativeMobileResources.TakePicture

	const fullPathWithoutFileScheme = fullPath.replace("file://", "");

	return new Promise((resolve, reject) => {
		NativeModules.MxFileSystem.read(fullPathWithoutFileScheme)
		.then((nativeBlob) => {
			const blob = new Blob();
			Object.assign(blob, { data: nativeBlob });
			const onSuccess = () => resolve(true);
			const onError = (error) => {
				// If this fails, always write a log entry
				NativeFileDocumentsUtils.writeToLog({
					actionName: "saveToMendixFileDocument",
					logType: "Exception",
					logMessage: JSON.stringify(error)
				}).then(() => {
					reject(error)
				});
			};
			// Set nativePayload so the patched FormData.prototype.append in NativeFileBackend
			// replaces the blob value with { uri, name, type } for online uploads. The patch
			// reads the third append() argument (fileName) and writes it onto nativePayload.name,
			// which FormData.getParts() uses as the Content-Disposition filename.
			blob.nativePayload = { uri: `file://${fullPathWithoutFileScheme}`, name: fileName, type: "*/*" };
			mx.data.saveDocument(guid, fileName, { width: 180, height: 180 }, blob, onSuccess, onError);
		})
		.catch(error => reject(error));
	});

	// END USER CODE
}
